solution.camicia.zig:
const std = @import("std");

pub const Status = enum { finished, loop };
pub const Result = struct { status: Status, cards: usize, tricks: usize };
fn value(card: []const u8) u8 {
    if (std.mem.eql(u8, card, "J")) return 1;
    if (std.mem.eql(u8, card, "Q")) return 2;
    if (std.mem.eql(u8, card, "K")) return 3;
    if (std.mem.eql(u8, card, "A")) return 4;
    return 0;
}
pub fn simulateGame(allocator: std.mem.Allocator, player_a: []const []const u8, player_b: []const []const u8) !Result {
    var hands = [_]std.array_list.Managed(u8){ std.array_list.Managed(u8).init(allocator), std.array_list.Managed(u8).init(allocator) };
    defer {
        hands[0].deinit();
        hands[1].deinit();
    }
    for (player_a) |c| try hands[0].append(value(c));
    for (player_b) |c| try hands[1].append(value(c));
    var pile = std.array_list.Managed(u8).init(allocator);
    defer pile.deinit();
    var seen = std.StringHashMap(void).init(allocator);
    defer {
        var it = seen.keyIterator();
        while (it.next()) |key| allocator.free(key.*);
        seen.deinit();
    }
    var turn: usize = 0;
    var debt: u8 = 0;
    var cards: usize = 0;
    var tricks: usize = 0;
    while (true) {
        if (pile.items.len == 0) {
            const state = try allocator.alloc(u8, hands[0].items.len + hands[1].items.len + 2);
            @memcpy(state[0..hands[0].items.len], hands[0].items);
            state[hands[0].items.len] = 255;
            @memcpy(state[hands[0].items.len + 1 .. state.len - 1], hands[1].items);
            state[state.len - 1] = @intCast(turn);
            if (seen.contains(state)) {
                allocator.free(state);
                return .{ .status = .loop, .cards = cards, .tricks = tricks };
            }
            seen.put(state, {}) catch |err| {
                allocator.free(state);
                return err;
            };
        }
        if (hands[turn].items.len == 0) return .{ .status = .finished, .cards = cards, .tricks = tricks + @as(usize, if (pile.items.len > 0) 1 else 0) };
        const card = hands[turn].orderedRemove(0);
        try pile.append(card);
        cards += 1;
        if (card > 0) {
            debt = card;
            turn = 1 - turn;
        } else if (debt > 0) {
            debt -= 1;
            if (debt == 0) {
                try hands[1 - turn].appendSlice(pile.items);
                pile.clearRetainingCapacity();
                tricks += 1;
                if (hands[0].items.len == 0 or hands[1].items.len == 0) return .{ .status = .finished, .cards = cards, .tricks = tricks };
                turn = 1 - turn;
            }
        } else turn = 1 - turn;
    }
}

